1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Calculator</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0; min-height: 100vh; display: flex; align-items: center; justify-content: center;
11	    background: #eceef1; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
12	  }
13	  .calc {
14	    width: min(320px, 100vw - 32px); padding: 16px; border-radius: 20px;
15	    background: #1f2227; box-shadow: 0 12px 32px rgba(0,0,0,.25);
16	  }
17	  .display {
18	    height: 80px; margin-bottom: 16px; padding: 0 12px; border-radius: 12px;
19	    background: #2b2f36; color: #fff; font-size: 40px; text-align: right;
20	    line-height: 80px; overflow: hidden; white-space: nowrap; text-overflow: ellipsis;
21	  }
22	  .keys { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; }
23	  button {
24	    height: 60px; border: 0; border-radius: 12px; font-size: 22px; cursor: pointer;
25	    background: #3a3f47; color: #fff;
26	  }
27	  button:active { filter: brightness(1.25); }
28	  .op { background: #f59e0b; }
29	  .clear { background: #9ca3af; color: #111; }
30	  .wide { grid-column: span 2; }
31	  .mem { font-size: 18px; }
32	  .mem-indicator {
33	    display: flex; align-items: center; justify-content: center; font-size: 15px; font-weight: 600;
34	    color: #4b5058;
35	  }
36	  .mem-indicator[data-active="true"] { color: #f59e0b; }
37	  .tape { margin-top: 16px; border-radius: 12px; background: #2b2f36; color: #fff; }
38	  .tape-head {
39	    display: flex; align-items: center; justify-content: space-between; padding: 8px 12px;
40	    font-size: 13px; color: #9ca3af;
41	  }
42	  .tape-clear { height: auto; padding: 4px 10px; font-size: 13px; border-radius: 8px; }
43	  .tape-list { max-height: 180px; overflow-y: auto; }
44	  .tape-row { padding: 6px 12px; border-top: 1px solid #3a3f47; text-align: right; }
45	  .tape-expr { font-size: 13px; color: #9ca3af; overflow-wrap: anywhere; }
46	  .tape-result { font-size: 20px; }
47	</style>
48	</head>
49	<body>
50	<div class="calc">
51	  <div class="display" data-testid="calc-display" data-value="0" data-error="false">0</div>
52	  <div class="keys">
53	    <div class="mem-indicator" data-testid="mem-indicator" data-active="false">M</div>
54	    <button class="mem" data-testid="key-mc">MC</button>
55	    <button class="mem" data-testid="key-mr">MR</button>
56	    <button class="mem" data-testid="key-mplus">M+</button>
57	    <button class="clear wide" data-testid="key-clear">AC</button>
58	    <button class="clear" data-testid="key-sign">±</button>
59	    <button class="op" data-testid="key-div" data-op="/">÷</button>
60	    <button class="clear wide" data-testid="key-lparen">(</button>
61	    <button class="clear wide" data-testid="key-rparen">)</button>
62	    <button data-testid="key-7" data-digit="7">7</button>
63	    <button data-testid="key-8" data-digit="8">8</button>
64	    <button data-testid="key-9" data-digit="9">9</button>
65	    <button class="op" data-testid="key-mul" data-op="*">×</button>
66	    <button data-testid="key-4" data-digit="4">4</button>
67	    <button data-testid="key-5" data-digit="5">5</button>
68	    <button data-testid="key-6" data-digit="6">6</button>
69	    <button class="op" data-testid="key-sub" data-op="-">−</button>
70	    <button data-testid="key-1" data-digit="1">1</button>
71	    <button data-testid="key-2" data-digit="2">2</button>
72	    <button data-testid="key-3" data-digit="3">3</button>
73	    <button class="op" data-testid="key-add" data-op="+">+</button>
74	    <button class="wide" data-testid="key-0" data-digit="0">0</button>
75	    <button data-testid="key-dot">.</button>
76	    <button class="op" data-testid="key-equals">=</button>
77	  </div>
78	  <div class="tape" data-testid="calc-tape">
79	    <div class="tape-head">
80	      <span>History</span>
81	      <button class="tape-clear" data-testid="tape-clear">Clear</button>
82	    </div>
83	    <div class="tape-list"></div>
84	  </div>
85	</div>
86	<script>
87	  var entry = "0";      // text of the current entry or last result
88	  var stored = null;    // left operand
89	  var op = null;        // pending operator
90	  var fresh = true;     // next digit starts a new entry
91	  var waiting = false;  // an operator was just pressed and has no right operand yet
92	  var error = false;    // set by a non-finite result; only clear leaves it
93	  var groups = [];      // outer {stored, op} saved by each open parenthesis
94	  var parts = [];       // expression text of the current group, for the tape
95	  var partGroups = [];  // outer parts saved by each open parenthesis
96	  var operandText = null; // text of a just-closed group, standing in for the entry
97	  var memory = 0;       // unrounded; survives AC
98	  var SYMBOLS = { "+": "+", "-": "\u2212", "*": "\u00d7", "/": "\u00f7" };
99	
100	  var display = document.querySelector('[data-testid="calc-display"]');
101	  var tapeList = document.querySelector(".tape-list");
102	  var memIndicator = document.querySelector('[data-testid="mem-indicator"]');
103	
104	  // Text of the current right operand as it belongs in the expression.
105	  function operandString() {
106	    if (operandText !== null) return operandText;
107	    return fresh ? format(Number(entry)) : entry.replace(/\.$/, "");
108	  }
109	
110	  function addTapeRow(expr, value) {
111	    var row = document.createElement("div");
112	    row.className = "tape-row";
113	    row.setAttribute("data-testid", "tape-row");
114	    var e = document.createElement("div");
115	    e.className = "tape-expr";
116	    e.setAttribute("data-testid", "tape-expr");
117	    e.textContent = expr;
118	    var r = document.createElement("div");
119	    r.className = "tape-result";
120	    r.setAttribute("data-testid", "tape-result");
121	    r.setAttribute("data-value", String(value));
122	    r.textContent = format(value);
123	    row.appendChild(e);
124	    row.appendChild(r);
125	    tapeList.insertBefore(row, tapeList.firstChild);
126	  }
127	
128	  function compute(a, b, o) {
129	    if (o === "+") return a + b;
130	    if (o === "-") return a - b;
131	    if (o === "*") return a * b;
132	    return a / b;
133	  }
134	
135	  // Presentation only: at most 10 significant digits, no trailing zeros,
136	  // exponential below 1e-9 or from 1e10. Stored values are never rounded.
137	  function format(v) {
138	    if (v === 0) return "0";
139	    var r = Number(v.toPrecision(10));
140	    var a = Math.abs(r);
141	    if (a >= 1e10 || a < 1e-9) return r.toExponential();
142	    var e = Math.floor(Math.log10(a));
143	    if (Math.pow(10, e) > a) e--;
144	    var s = r.toFixed(Math.max(0, 9 - e));
145	    return s.indexOf(".") === -1 ? s : s.replace(/0+$/, "").replace(/\.$/, "");
146	  }
147	
148	  // While typing, the entry shows exactly as typed; results are formatted.
149	  function render() {
150	    display.textContent = error ? "Error" : fresh ? format(Number(entry)) : entry;
151	    display.setAttribute("data-value", String(Number(entry)));
152	    display.setAttribute("data-error", String(error));
153	    memIndicator.setAttribute("data-active", String(memory !== 0));
154	  }
155	
156	  function digit(d) {
157	    if (fresh) { entry = d; fresh = false; }
158	    else entry = entry === "0" || entry === "-0" ? entry.slice(0, -1) + d : entry + d;
159	    waiting = false;
160	    operandText = null;
161	  }
162	
163	  function dot() {
164	    if (fresh) { entry = "0."; fresh = false; }
165	    else if (entry.indexOf(".") === -1) entry += ".";
166	    waiting = false;
167	    operandText = null;
168	  }
169	
170	  // Acts on the current entry. A typed entry keeps its text; a result is negated as a value.
171	  function sign() {
172	    if (!fresh) entry = entry.charAt(0) === "-" ? entry.slice(1) : "-" + entry;
173	    else entry = String(-Number(entry));
174	    waiting = false;
175	    operandText = null;
176	  }
177	
178	  // Immediate execution: each operator finishes the waiting operation, strictly
179	  // left to right, no precedence. 2 + 3 × 4 = is 20. The display always shows a real result.
180	  function operator(o) {
181	    if (waiting) parts[parts.length - 1] = SYMBOLS[o];
182	    else parts.push(operandString(), SYMBOLS[o]);
183	    operandText = null;
184	    if (op !== null && !waiting) finish(compute(stored, Number(entry), op));
185	    stored = Number(entry);
186	    op = o;
187	    fresh = true;
188	    waiting = true;
189	  }
190	
191	  // Division by zero (or any non-finite result) enters the error state.
192	  function finish(result) {
193	    entry = String(result);
194	    if (!isFinite(result)) error = true;
195	  }
196	
197	  // A group saves the outer operation and starts a fresh one inside.
198	  // Inside a group the same left-to-right rule applies.
199	  function lparen() {
200	    partGroups.push(parts);
201	    parts = []; operandText = null;
202	    groups.push({ stored: stored, op: op });
203	    entry = "0"; stored = null; op = null; fresh = true; waiting = false;
204	  }
205	
206	  // Closing finishes the inner operation; its result becomes the outer right operand.
207	  function rparen() {
208	    if (groups.length === 0) return;
209	    if (waiting) parts.pop();
210	    else parts.push(operandString());
211	    var inner = "(" + parts.join(" ") + ")";
212	    parts = partGroups.pop();
213	    operandText = inner;
214	    if (op !== null && !waiting) finish(compute(stored, Number(entry), op));
215	    var g = groups.pop();
216	    stored = g.stored;
217	    op = g.op;
218	    fresh = true;
219	    waiting = false;
220	  }
221	
222	  // Equals closes any open groups first.
223	  function equals() {
224	    while (groups.length && !error) rparen();
225	    if (op === null || error) return;
226	    parts.push(operandString());
227	    finish(compute(stored, Number(entry), op));
228	    if (!error) addTapeRow(parts.join(" "), Number(entry));
229	    parts = []; operandText = null;
230	    stored = null;
231	    op = null;
232	    fresh = true;
233	    waiting = false;
234	  }
235	
236	  // M+ adds the unrounded displayed value. A non-finite sum is an error and leaves memory as it was.
237	  function memoryAdd() {
238	    var sum = memory + Number(entry);
239	    if (!isFinite(sum)) error = true;
240	    else memory = sum;
241	  }
242	
243	  // MR puts memory in the entry as a result: formatted, and the next digit starts a new entry.
244	  function memoryRecall() {
245	    entry = String(memory);
246	    fresh = true;
247	    waiting = false;
248	    operandText = null;
249	  }
250	
251	  function clear() {
252	    entry = "0"; stored = null; op = null; fresh = true; waiting = false; error = false; groups = [];
253	    parts = []; partGroups = []; operandText = null;
254	  }
255	
256	  document.querySelector(".keys").addEventListener("click", function (e) {
257	    var b = e.target.closest("button");
258	    if (!b) return;
259	    var id = b.getAttribute("data-testid");
260	    if (error && id !== "key-clear") return;
261	    if (b.hasAttribute("data-digit")) digit(b.getAttribute("data-digit"));
262	    else if (b.hasAttribute("data-op")) operator(b.getAttribute("data-op"));
263	    else if (id === "key-dot") dot();
264	    else if (id === "key-sign") sign();
265	    else if (id === "key-lparen") lparen();
266	    else if (id === "key-rparen") rparen();
267	    else if (id === "key-equals") equals();
268	    else if (id === "key-clear") clear();
269	    else if (id === "key-mplus") memoryAdd();
270	    else if (id === "key-mr") memoryRecall();
271	    else if (id === "key-mc") memory = 0;
272	    render();
273	  });
274	
275	  // Clearing the tape leaves the calculator untouched.
276	  document.querySelector('[data-testid="tape-clear"]').addEventListener("click", function () {
277	    tapeList.textContent = "";
278	  });
279	
280	  render();
281	</script>
282	</body>
283	</html>
